// Integrity gate for the INGESTED jobs layer (roadmap item B).
//
// src/data/jobsExternal.*.ts is AUTO-GENERATED by scripts/ingest/jobsExternal.cjs
// and is published to the public site, so every row must be traceable:
//   · provenance  — which external board it came from (never blank)
//   · verifiedAt  — ISO YYYY-MM-DD stamp from the run that produced it
//   · url         — https:// or nothing (Zero Trust: no fabricated links)
//   · no duplicate company against the curated seed (jobsData.json)
//
// If this test fails, fix the SOURCE or the ingest script and re-run it —
// never hand-edit the generated module.

import { describe, it, expect } from 'vitest';

import jobsSeed from '../jobsData.json';
import { externalJobs_80000hours } from '../jobsExternal.80000hours';

const externalJobs = [...externalJobs_80000hours];
const seedCompanies = new Set(jobsSeed.map((j) => String(j.company).trim().toLowerCase()));

describe('ingested external jobs integrity', () => {
  it('has at least one ingested entry', () => {
    expect(externalJobs.length).toBeGreaterThan(0);
  });

  it('every entry carries provenance + a verifiedAt ISO date', () => {
    const bad = externalJobs.filter(
      (j) => !j.provenance || !/^\d{4}-\d{2}-\d{2}$/.test(j.verifiedAt ?? ''),
    );
    expect(bad.map((j) => j.company)).toEqual([]);
  });

  it('every entry links out over https (or not at all)', () => {
    const bad = externalJobs.filter((j) => j.url && !/^https:\/\/\S+$/.test(j.url));
    expect(bad.map((j) => `${j.company} ${j.url}`)).toEqual([]);
  });

  it('every entry has a company, a category and a positive role count', () => {
    const bad = externalJobs.filter(
      (j) => !j.company.trim() || !j.category.trim() || !(Number(j.count) > 0),
    );
    expect(bad.map((j) => j.company)).toEqual([]);
  });

  it('does not duplicate a company already in the curated seed', () => {
    const dupes = externalJobs
      .map((j) => j.company.trim().toLowerCase())
      .filter((c) => seedCompanies.has(c));
    expect(dupes).toEqual([]);
  });

  it('ingested companies are unique within the ingested layer', () => {
    const seen = new Set<string>();
    const dupes: string[] = [];
    for (const j of externalJobs) {
      const key = j.company.trim().toLowerCase();
      if (seen.has(key)) dupes.push(j.company);
      seen.add(key);
    }
    expect(dupes).toEqual([]);
  });
});
